mapper.insert:
/* PEAAutoChargeDAO.insertChrgAcnt */
INSERT INTO AP_CUST_CHRG_ACNT_MNG (
    MCUST_NO
  , ACNT_SEQ
  , CUST_KEY
  , BILL_KEY
  , BANK_GBCD
  , RGST_ID
  , RGST_IP
  , REG_DTM
  , CHGP_ID
  , CHGP_IP
  , CHG_DTM
) VALUES (
    #{mcustNo}
  , AP_CUST_CHRG_ACNT_MNG_SEQ.NEXTVAL
  , #{custKey}
  , #{billKey}
  , #{bankGbcd}
  , #{rgstId}
  , #{rgstIp}
  , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
  , #{chgpId}
  , #{chgpIp}
  , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
)

mapper.select:
/* PEAAutoChargeDAO.selectChrgAcntList */
SELECT

FROM
    AP_CUST_CHRG_ACNT_MNG


        AND MCUST_NO = #{mcustNo}


        AND ACNT_SEQ = #{acntSeq}


ORDER BY
    LVL_PRTY ASC
